PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?person ?name ?birthDate WHERE {
  VALUES ?person { dbr:Darar_Djama_Aboubaker dbr:Michal_Pavlů }

  OPTIONAL { ?person dbp:birthDate ?b1 . }
  OPTIONAL { ?person dbo:birthDate ?b2 . }
  BIND (COALESCE(?b1, ?b2) AS ?birthDate)

  OPTIONAL { ?person dbp:name ?n1 . }
  OPTIONAL { ?person rdfs:label ?n2 . FILTER (lang(?n2) = "en") }
  BIND (COALESCE(?n1, ?n2) AS ?name)
}
LIMIT 100

